from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
COMP = ROOT / 'supabase/functions/scout-component-sandbox-mcp'
SHARED = ROOT / 'supabase/functions/_shared'
MIGRATIONS = ROOT / 'supabase/migrations'


def write(path: Path, text: str):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text.rstrip() + '\n')


def replace_once(path: Path, old: str, new: str):
    text = path.read_text()
    if old not in text:
        raise RuntimeError(f'anchor not found in {path}: {old[:100]!r}')
    text = text.replace(old, new, 1)
    path.write_text(text)


def append_once(path: Path, marker: str, text: str):
    current = path.read_text()
    if marker not in current:
        path.write_text(current.rstrip() + '\n\n' + text.rstrip() + '\n')


